//! Shared helpers for comparing waveforms against LALSimulation reference data.
//!
//! The reference data are generated by `scripts/generate_reference_data.py`.
#![allow(dead_code)]

use num_complex::Complex;
use serde::Deserialize;

pub type C64 = Complex<f64>;

#[derive(Debug, Deserialize)]
pub struct ReferenceFile {
    pub lalsimulation_version: String,
    pub cases: Vec<Case>,
}

#[derive(Debug, Deserialize, Clone)]
pub struct Case {
    pub approximant: String,
    pub mass_1: f64,
    pub mass_2: f64,
    pub spin_1: [f64; 3],
    pub spin_2: [f64; 3],
    pub luminosity_distance: f64,
    pub inclination: f64,
    pub phi_ref: f64,
    pub f_min: f64,
    pub f_ref: f64,
    pub f_max: f64,
    pub frequencies: Vec<f64>,
    pub hplus_real: Vec<f64>,
    pub hplus_imag: Vec<f64>,
    pub hcross_real: Vec<f64>,
    pub hcross_imag: Vec<f64>,
    /// Waveform flags inserted in the LALDict (e.g. `PhenomXPrecVersion`).
    #[serde(default)]
    pub lal_flags: std::collections::HashMap<String, f64>,
    /// LAL's mode array `(l, m)`, empty for the default modes.
    #[serde(default)]
    pub mode_array: Vec<(u32, i32)>,
}

impl Case {
    pub fn total_mass(&self) -> f64 {
        self.mass_1 + self.mass_2
    }

    /// Mass ratio in the `waveformrs` convention, q = m2 / m1 <= 1.
    pub fn mass_ratio(&self) -> f64 {
        self.mass_2 / self.mass_1
    }

    pub fn hplus(&self) -> Vec<C64> {
        zip_complex(&self.hplus_real, &self.hplus_imag)
    }

    pub fn hcross(&self) -> Vec<C64> {
        zip_complex(&self.hcross_real, &self.hcross_imag)
    }

    pub fn label(&self) -> String {
        format!(
            "{} m1={} m2={} s1={:?} s2={:?} iota={} phi={} fref={}",
            self.approximant,
            self.mass_1,
            self.mass_2,
            self.spin_1,
            self.spin_2,
            self.inclination,
            self.phi_ref,
            self.f_ref
        )
    }
}

fn zip_complex(re: &[f64], im: &[f64]) -> Vec<C64> {
    re.iter().zip(im).map(|(&r, &i)| C64::new(r, i)).collect()
}

/// The NRSur7dq4 data, located as `waveformrs::nrsur::find_data_file` does
/// (`NRSUR7DQ4_DATA`, `LAL_DATA_PATH`) or else in `<CARGO_MANIFEST_DIR>/lal_data/`;
/// `None`, with a message, when it is not available.
#[allow(dead_code)]
pub fn nrsur7dq4_data() -> Option<&'static waveformrs::nrsur::NRSur7dq4Data> {
    if waveformrs::nrsur::find_data_file().is_none() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("lal_data")
            .join(waveformrs::nrsur::NRSUR7DQ4_DATAFILE);
        if !path.is_file() {
            println!(
                "skipping: {} not found (set NRSUR7DQ4_DATA or LAL_DATA_PATH)",
                waveformrs::nrsur::NRSUR7DQ4_DATAFILE
            );
            return None;
        }
        std::env::set_var("NRSUR7DQ4_DATA", path);
    }
    waveformrs::nrsur::NRSur7dq4Data::global().ok()
}

/// The reference data `<name>.json`: from the directory in
/// `WAVEFORMRS_REFERENCE_DATA` if set and it has the suite (data generated
/// with the lalsimulation of this machine, e.g. by
/// `scripts/linux/reference.sh`), else from the committed `tests/data` (the
/// conda-forge osx-arm64 build of lalsimulation, and for the
/// `imrphenomxpnr_parityfix*` suites that build of 6.2.0 with lalsuite
/// !2593).
pub fn data_path(name: &str) -> std::path::PathBuf {
    let file = format!("{name}.json");
    if let Some(dir) = std::env::var_os("WAVEFORMRS_REFERENCE_DATA") {
        let path = std::path::PathBuf::from(dir).join(&file);
        if path.exists() {
            return path;
        }
    }
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/data")
        .join(file)
}

/// Tolerances `(relative error, mismatch)` of the suites that amplify
/// rounding errors, on every platform. The crate does not reproduce any
/// build of lalsimulation operation by operation (it uses Rust's elementary
/// functions and fuses multiply-adds where the hardware can), and the
/// ill-conditioned parts of the models turn last-bit differences into much
/// larger ones, in LAL itself as much as here (docs/linux.md): the
/// IMRPhenomXHM (3,2) mode (relative ~2e-3 between LAL's own Linux and
/// macOS builds) and, through it, every IMRPhenomXHM/XPHM polarisation and
/// the l = 3 modes of IMRPhenomXPHM, the MSA angles and the SpinTaylor
/// angles. The values are about ten times the largest differences seen
/// between this crate on macOS and Linux (arm64 and amd64) and either the
/// osx-arm64 or the Linux lalsimulation, which are themselves of the size
/// of the differences between lalsimulation's own builds
/// (report/data/linux_reference_comparison.json).
const AMPLIFYING_SUITE_TOLERANCES: [(&str, (f64, f64)); 28] = [
    ("imrphenomxhm", (1e-3, 1e-6)),
    // the (3,+-2) modes, and the others (up to 2e-9 at mass ratio 30 in the
    // containers of docs/linux.md; on the Ubuntu runners of GitHub Actions
    // up to 1.8e-2 / 1.8e-4 for (3,-2) and 4e-8 for the others, in the
    // release-122019 modes of src/imrphenomx/xhm/release_122019_tests.rs)
    ("imrphenomxhm_modes_32", (2e-1, 2e-3)),
    ("imrphenomxhm_modes", (4e-7, 1e-12)),
    // the l = 3 modes of IMRPhenomXHM and XPHM (tests/modes.rs)
    ("choose_fd_modes_l3", (2e-2, 4e-5)),
    ("choose_fd_modes", (1e-8, 1e-12)),
    ("imrphenomxphm_spintaylor", (1e-3, 1e-6)),
    ("imrphenomxphm_nnlo", (1e-3, 1e-6)),
    ("imrphenomxphm_msa", (1e-3, 1e-6)),
    ("imrphenomxphm_uniform", (1e-3, 1e-6)),
    ("imrphenomxphm_modes", (1e-3, 1e-6)),
    ("imrphenomxphm_spintaylor_fallback", (1e-3, 1e-6)),
    // IMRPhenomXHM release 122019 and IMRPhenomXPNR (which uses it, with
    // the fix of lalsuite !2593, tests/xpnr.rs), not yet compared with a
    // Linux lalsimulation: those of IMRPhenomXHM/XPHM
    // (mismatch up to 1.2e-6 on Linux arm64 at mass ratio 100)
    ("imrphenomxhm_122019", (1e-3, 1e-5)),
    ("imrphenomxpnr_parityfix", (1e-3, 1e-6)),
    ("imrphenomxpnr_parityfix_uniform", (1e-3, 1e-6)),
    ("imrphenomxpnr_parityfix_modes", (1e-3, 1e-6)),
    ("imrphenomxpnr_parityfix_modes_l3", (2e-2, 4e-5)),
    ("imrphenomxp_msa", (1e-7, 1e-12)),
    // the SpinTaylor angles of IMRPhenomXP_NRTidalv2/v3, whose start is
    // sensitive to the last bit of the quadrupole-monopole parameter (up to
    // 6e-8 on Linux arm64 against the committed data)
    ("imrphenomxp_nrtidalv2", (1e-6, 1e-12)),
    ("imrphenomxp_nrtidalv3", (1e-6, 1e-12)),
    ("nrtidal_uniform", (1e-6, 1e-12)),
    // absolute difference of the Euler angles
    ("imrphenomxp_spintaylor_angles", (1e-9, 0.0)),
    // spin components and the like, relative to their largest value
    ("spintaylor", (1e-6, 0.0)),
    // tests/conversions.rs: SimInspiralTD/FD of the higher-mode models
    ("conversions IMRPhenomXHM", (1e-3, 0.0)),
    ("conversions IMRPhenomXPHM", (1e-3, 0.0)),
    // tests/long_waveforms.rs: lower bounds of its tolerances
    ("long IMRPhenomXHM", (1e-5, 0.0)),
    ("long IMRPhenomXP", (1e-7, 0.0)),
    ("long IMRPhenomXPHM", (1e-5, 0.0)),
    // absolute, the Euler angles after ~900 s of SpinTaylor integration
    ("spintaylor_angles_long", (1e-5, 0.0)),
];

/// The tolerances of `suite`: the looser of `strict` and those of
/// [`AMPLIFYING_SUITE_TOLERANCES`].
pub fn tolerances(suite: &str, strict: (f64, f64)) -> (f64, f64) {
    AMPLIFYING_SUITE_TOLERANCES
        .iter()
        .find(|(name, _)| *name == suite)
        .map_or(strict, |&(_, (rel, mm))| {
            (rel.max(strict.0), mm.max(strict.1))
        })
}

pub fn load(name: &str) -> ReferenceFile {
    let path = data_path(name);
    let contents =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&contents).unwrap()
}

/// Trapezoid-like weights for a non-uniform frequency grid.
fn weights(frequencies: &[f64]) -> Vec<f64> {
    let n = frequencies.len();
    (0..n)
        .map(|i| {
            let lo = frequencies[i.saturating_sub(1)];
            let hi = frequencies[(i + 1).min(n - 1)];
            0.5 * (hi - lo)
        })
        .collect()
}

#[derive(Debug, Clone, Copy)]
pub struct Comparison {
    /// max_i |a_i - b_i| / max_i |b_i|
    pub max_relative_error: f64,
    /// 1 - Re<a, b> / sqrt(<a, a><b, b>) with a white noise spectrum,
    /// no maximization over time or phase.
    pub mismatch: f64,
}

pub fn compare(frequencies: &[f64], test: &[C64], reference: &[C64]) -> Comparison {
    assert_eq!(test.len(), reference.len());
    let w = weights(frequencies);
    let mut ab = 0.0;
    let mut aa = 0.0;
    let mut bb = 0.0;
    let mut max_diff: f64 = 0.0;
    let mut max_ref: f64 = 0.0;
    for ((a, b), w) in test.iter().zip(reference).zip(&w) {
        ab += w * (a * b.conj()).re;
        aa += w * a.norm_sqr();
        bb += w * b.norm_sqr();
        max_diff = max_diff.max((a - b).norm());
        max_ref = max_ref.max(b.norm());
    }
    let mismatch = if aa == 0.0 && bb == 0.0 {
        0.0
    } else {
        1.0 - ab / (aa * bb).sqrt()
    };
    Comparison {
        max_relative_error: if max_ref > 0.0 {
            max_diff / max_ref
        } else {
            max_diff
        },
        mismatch,
    }
}

/// Compare both polarizations of every case and panic with a summary if any
/// exceeds the tolerances (those given, or those of [`tolerances`] where the
/// crate does not mirror the reference build).
pub fn check_all<F>(name: &str, max_relative_error: f64, max_mismatch: f64, generate: F)
where
    F: Fn(&Case) -> (Vec<C64>, Vec<C64>),
{
    let (max_relative_error, max_mismatch) = tolerances(name, (max_relative_error, max_mismatch));
    let reference = load(name);
    let mut failures = Vec::new();
    for case in &reference.cases {
        let (hp, hc) = generate(case);
        for (pol, test, truth) in [("plus", hp, case.hplus()), ("cross", hc, case.hcross())] {
            let result = compare(&case.frequencies, &test, &truth);
            println!(
                "{pol:>5}: max rel err {:.3e}, mismatch {:.3e} | {}",
                result.max_relative_error,
                result.mismatch,
                case.label()
            );
            if !(result.max_relative_error <= max_relative_error && result.mismatch <= max_mismatch)
            {
                failures.push(format!("{pol} {:?} {}", result, case.label()));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} comparisons failed (tolerances: rel {max_relative_error:e}, mismatch {max_mismatch:e}) against lalsimulation {}:\n{}",
        failures.len(),
        reference.lalsimulation_version,
        failures.join("\n")
    );
}
